        }
      ]
    },
    {
      "question": "What protective equipment is required in the woodworking zone and when is hearing protection mandatory?",
      "kind": "answerable",
      "expected_status": "answered",
      "facts": [
        {
          "chunk_id": "973de2cb039dbd1c",
          "quote": "Safety glasses are required in the woodworking zone even when a member is observing. Hearing protection is required when the posted machine notice specifies it."
        }
      ]
    }
  ]
}
